#!/usr/bin/env node
/**
 * File Watcher Daemon
 *
 * Monitors a target folder and logs all filename events to events.log.
 * - Uses fs.watch for OS-level inotify/FSEvents integration
 * - SIGHUP: reopen log file (log rotation support)
 * - SIGTERM / SIGINT: graceful shutdown with final log flush
 * - SIGUSR1: dump current watcher status to log
 * - Restarts watcher automatically if the watched directory is recreated
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ── Configuration ──────────────────────────────────────────────────────────────
const WATCH_DIR  = process.env.WATCH_DIR  || path.join(__dirname, 'watched');
const LOG_FILE   = process.env.LOG_FILE   || path.join(__dirname, 'events.log');
const PID_FILE   = process.env.PID_FILE   || path.join(__dirname, 'daemon.pid');
const POLL_MS    = parseInt(process.env.POLL_MS || '200', 10); // fallback poll interval

// ── State ──────────────────────────────────────────────────────────────────────
let logStream  = null;
let watcher    = null;
let retryTimer = null;
let shuttingDown = false;

// ── Helpers ────────────────────────────────────────────────────────────────────
function timestamp() {
  return new Date().toISOString();
}

function openLog() {
  if (logStream) {
    try { logStream.end(); } catch (_) {}
  }
  logStream = fs.createWriteStream(LOG_FILE, { flags: 'a', encoding: 'utf8' });
  logStream.on('error', (err) => {
    process.stderr.write(`[${timestamp()}] LOG STREAM ERROR: ${err.message}\n`);
  });
}

function log(eventType, filename, extra) {
  if (!logStream || logStream.destroyed || logStream.closed) openLog();
  const parts = [timestamp(), eventType, filename || ''];
  if (extra) parts.push(extra);
  const line = parts.join('\t') + '\n';
  logStream.write(line);
  process.stdout.write(line);
}

function writePid() {
  try {
    fs.writeFileSync(PID_FILE, String(process.pid), 'utf8');
  } catch (err) {
    process.stderr.write(`[${timestamp()}] Could not write PID file: ${err.message}\n`);
  }
}

function removePid() {
  try { fs.unlinkSync(PID_FILE); } catch (_) {}
}

// ── Watcher ────────────────────────────────────────────────────────────────────
function startWatcher() {
  if (watcher) {
    try { watcher.close(); } catch (_) {}
    watcher = null;
  }

  if (!fs.existsSync(WATCH_DIR)) {
    log('WARN', '', `Watch dir missing: ${WATCH_DIR} — retrying in ${POLL_MS}ms`);
    retryTimer = setTimeout(startWatcher, POLL_MS);
    return;
  }

  log('START', '', `Watching: ${WATCH_DIR}`);

  try {
    watcher = fs.watch(WATCH_DIR, { persistent: true }, (eventType, filename) => {
      if (filename) {
        log(eventType.toUpperCase(), filename);
      } else {
        // Some platforms don't supply filename; do a stat-based diff
        log(eventType.toUpperCase(), '<unknown>', 'filename not provided by OS');
      }
    });

    watcher.on('error', (err) => {
      log('WATCHER_ERROR', '', err.message);
      // Restart watcher on error
      if (!shuttingDown) {
        retryTimer = setTimeout(startWatcher, POLL_MS);
      }
    });

    watcher.on('close', () => {
      if (!shuttingDown) {
        log('WATCHER_CLOSED', '', 'Unexpected close — restarting');
        retryTimer = setTimeout(startWatcher, POLL_MS);
      }
    });

  } catch (err) {
    log('WATCHER_FAIL', '', err.message);
    if (!shuttingDown) {
      retryTimer = setTimeout(startWatcher, POLL_MS);
    }
  }
}

// ── Signal Handlers ────────────────────────────────────────────────────────────

// SIGHUP — reopen log (standard log-rotation signal)
process.on('SIGHUP', () => {
  log('SIGNAL', 'SIGHUP', 'Reopening log file');
  openLog();
  log('LOG_REOPENED', '', LOG_FILE);
});

// SIGUSR1 — status dump
process.on('SIGUSR1', () => {
  log('STATUS', '', JSON.stringify({
    pid:      process.pid,
    watchDir: WATCH_DIR,
    logFile:  LOG_FILE,
    watching: watcher !== null,
    uptime:   process.uptime().toFixed(1) + 's',
    mem:      process.memoryUsage().rss,
  }));
});

// SIGTERM / SIGINT — graceful shutdown
function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  clearTimeout(retryTimer);

  log('SIGNAL', signal, 'Shutting down');

  if (watcher) {
    try { watcher.close(); } catch (_) {}
  }

  removePid();

  // Flush and close log stream, then exit
  if (logStream && !logStream.destroyed) {
    logStream.end(() => process.exit(0));
    // Safety timeout in case end() hangs
    setTimeout(() => process.exit(0), 2000).unref();
  } else {
    process.exit(0);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// Uncaught errors — log and keep running (don't crash the daemon)
process.on('uncaughtException', (err) => {
  log('UNCAUGHT_EXCEPTION', '', err.stack || err.message);
});

process.on('unhandledRejection', (reason) => {
  log('UNHANDLED_REJECTION', '', String(reason));
});

// ── Bootstrap ──────────────────────────────────────────────────────────────────
writePid();
openLog();
log('BOOT', '', `PID=${process.pid}  WATCH_DIR=${WATCH_DIR}  LOG_FILE=${LOG_FILE}`);

// Ensure the watched directory exists
try {
  fs.mkdirSync(WATCH_DIR, { recursive: true });
} catch (err) {
  log('WARN', '', `Could not create watch dir: ${err.message}`);
}

startWatcher();
